    [3267]={name="Forsaken Shortsword",quality=1,ilvl=5,reqLevel=2,sourceType="quest_reward",instructions="Reward from the quest 'The Scarlet Crusade'. Pick it over the other reward choices. Starts with Executor Arren in Tirisfal Glades. Objective: Bring Executor Arren 12 Scarlet Armbands from Scarlet Converts and Scarlet Initiates.",zone="Tirisfal Glades",questName="The Scarlet Crusade",lore="You'll be happy to know we appear to be making progress in the mine, thanks in no small part to your efforts. We can now turn our eyes to other concerns."},
