    [3272]={name="Zombie Skin Leggings",quality=1,ilvl=5,reqLevel=2,sourceType="quest_reward",instructions="Reward from the quest 'Night Web's Hollow'. Pick it over the other reward choices. Starts with Executor Arren in Tirisfal Glades. Objective: Executor Arren wants you to kill 10 Young Night Web Spiders and 8 Night Web Spiders.",zone="Tirisfal Glades",questName="Night Web's Hollow",lore="One of our greatest struggles is obtaining the natural resources we need to survive. Gold was scarce even in the height of the Alliance's power."},
    [3273]={name="Rugged Mail Vest",quality=1,ilvl=5,reqLevel=2,sourceType="quest_reward",instructions="Reward from the quest 'Night Web's Hollow'. Pick it over the other reward choices. Starts with Executor Arren in Tirisfal Glades. Objective: Executor Arren wants you to kill 10 Young Night Web Spiders and 8 Night Web Spiders.",zone="Tirisfal Glades",questName="Night Web's Hollow",lore="One of our greatest struggles is obtaining the natural resources we need to survive. Gold was scarce even in the height of the Alliance's power."},
    [3274]={name="Flax Boots",quality=1,ilvl=5,reqLevel=1,sourceType="quest_reward",instructions="Reward from the quest 'Rattling the Rattlecages'. Pick it over the other reward choices. Starts with Shadow Priest Sarvis in Tirisfal Glades. Objective: Kill 12 Rattlecage Skeletons, and then return to Shadow Priest Sarvis in Deathknell when you are done.",zone="Tirisfal Glades",questName="Rattling the Rattlecages",lore="You've shown your potential to the Forsaken under normal circumstances - now let's see you under pressure. The Rattlecage skeletons, more mindless minions of the Lich King, are a tougher foe than the zombies you have faced thus far."},
    [3275]={name="Flax Gloves",quality=1,ilvl=5,reqLevel=1,sourceType="quest_reward",instructions="Reward from the quest 'The Mindless Ones'. Pick it over the other reward choices. Starts with Shadow Priest Sarvis in Tirisfal Glades. Objective: Shadow Priest Sarvis wants you to kill 8 Mindless Zombies and 8 Wretched Zombies.",zone="Tirisfal Glades",questName="The Mindless Ones",lore="We Forsaken are at war with the Lich King's army of the Scourge: necromantically raised armies of the undead, foul beasts of the north, and tormented spectres."},
    [3276]={name="Deathguard Buckler",quality=1,ilvl=5,reqLevel=2,sourceType="quest_reward",instructions="Reward from the quest 'The Red Messenger'. Pick it over the other reward choices. Starts with Executor Arren in Tirisfal Glades. Objective: Kill Meven Korgal, the messenger, at the Crusader camp, then return any information you find to Executor Arren.",zone="Tirisfal Glades",questName="The Red Messenger",lore="Reports from my superiors in Brill indicate that an agent of the Scarlet Crusade was dispatched from the Scarlet Monastery and sent here to Deathknell."},
