    [3437]={name="Clasped Belt",quality=1,ilvl=8,reqLevel=5,sourceType="quest_reward",instructions="Reward from the quest 'Proof of Demise'. Pick it over the other reward choices. Starts with Deathguard Burgess in Tirisfal Glades. Objective: Bring 10 Scarlet Insignia Rings to Deathguard Burgess in Brill.",zone="Tirisfal Glades",questName="Proof of Demise",lore="Executor Zygand tells me you've been out killing Scarlet Crusaders. Tirisfal Glades is crawling with them."},
    [3439]={name="Zombie Skin Boots",quality=1,ilvl=8,reqLevel=4,sourceType="quest_reward",instructions="Reward from the quest 'Graverobbers'. Pick it over the other reward choices. Starts with Magistrate Sevren in Tirisfal Glades. Objective: Kill Rot Hide Graverobbers and Rot Hide Mongrels. Bring 8 Embalming Ichors to Magistrate Sevren in Brill.",zone="Tirisfal Glades",questName="Graverobbers",lore="The Mass Graves, southwest of Garren's Haunt to the north, were made to accommodate the...impressive...number of deaths Tirisfal suffered when the Plague first came."},
    [3440]={name="Bonecracker",quality=2,ilvl=13,reqLevel=7,sourceType="quest_reward",instructions="Reward from the quest 'The Family Crypt'. Pick it over the other reward choices. Starts with Magistrate Sevren in Tirisfal Glades. Objective: Kill 8 Wailing Ancestors and 8 Rotting Ancestors.Kill Captain Dargol, and bring his skull to Magistrate Sevren in Brill.",zone="Tirisfal Glades",questName="The Family Crypt",lore="The Agamand Mills area has become a foothold for the Scourge. Their strongest point is the Agamand Family Crypt where their local military leader, a skeleton named Captain Dargol, has headquartered."},
    [3447]={name="Cryptwalker Boots",quality=1,ilvl=8,reqLevel=6,sourceType="quest_reward",instructions="Reward from the quest 'The Mills Overrun'. Pick it over the other reward choices. Starts with Deathguard Dillinger in Tirisfal Glades. Objective: Gather 5 Notched Ribs and 3 Blackened Skulls, then return to Deathguard Dillinger in Brill.",zone="Tirisfal Glades",questName="The Mills Overrun",lore="The Scourge are trying to form a base at the Agamand Mills. If they do, then they can stage further attacks within Tirisfal. The orders have been given."},
    [3451]={name="Nightglow Concoction",quality=2,ilvl=18,reqLevel=9,sourceType="quest_reward",instructions="Reward from the quest 'A Recipe For Death'. Pick it over the other reward choices. Starts with Apothecary Renferrel in Silverpine Forest. Objective: Bring 6 samples of Lake Creeper Moss, 6 samples of Lake Skulker Moss and a Hardened Tumor to Master Apothecary Faranell in the Undercity.",zone="Silverpine Forest",questName="A Recipe For Death",lore="According to Berard's Journal the moss from Lake Skulkers and Creepers might prove useful for our quest to brew a new plague. Those beasts dwell on the islands in Lake Lordamere to the east."},
