    [6713]={name="Ripped Pants",quality=1,ilvl=5,reqLevel=1,sourceType="quest_reward",instructions="Reward from the quest 'Burning Blade Medallion'. Pick it over the other reward choices. Starts with Zureetha Fargaze in Durotar. Objective: Bring the Burning Blade Medallion to Zureetha Fargaze, outside The Den.",zone="Durotar",questName="Burning Blade Medallion",lore="Through my divinations, I see that an item of power hides deep within the Burning Blade Coven, guarded by beasts and black magic. It is called the Burning Blade Medallion, and your next task is to find it and remove it from the coven."},
